CREATE TABLE wp_repro_ai_usage_log(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,property_id BIGINT UNSIGNED NULL,provider VARCHAR(32) NOT NULL,feature VARCHAR(32) NOT NULL,tokens_in INT UNSIGNED DEFAULT 0,tokens_out INT UNSIGNED DEFAULT 0,status VARCHAR(16) NOT NULL DEFAULT 'ok',created_at DATETIME NOT NULL,KEY user_date(user_id,created_at));
CREATE TABLE wp_repro_property_views(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,property_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NULL,ip_hash CHAR(64) NULL,created_at DATETIME NOT NULL,KEY property_date(property_id,created_at));
CREATE TABLE wp_repro_saved_searches(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,name VARCHAR(190) NOT NULL,criteria LONGTEXT NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'active',last_notified_at DATETIME NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,KEY user_status(user_id,status));